import java.util.*;

public class Main {
    static final int MOD = 777777777;

    static int modExp(int base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.close();

        // Case A: k == n
        if (k == n) {
            // A = n^n - C(n, 1)*(n-1)^n + C(n, 2)*(n-2)^n
            int term0 = modExp(n, n);
            int term1 = (int) (( (long) n * modExp(n - 1, n) ) % MOD);
            int term2 = 0;
            if (n >= 2) {
                long c2 = (long) n * (n - 1) / 2;
                term2 = (int) ( (c2 % MOD) * modExp(n - 2, n) % MOD );
            }
            int ans = (term0 - term1 + term2) % MOD;
            if (ans < 0) ans += MOD;
            System.out.println(ans);
        } else {
            // Case B: k < n
            int t = n - k;
            // compute C(n, t)
            long c = 1;
            for (int i = 1; i <= t; i++) {
                c = c * (n - i + 1) / i;
            }
            int cMod = (int) (c % MOD);
            int waysLiars = modExp(n - 1, k);
            int ans = (int) ((cMod * (long) waysLiars) % MOD);
            System.out.println(ans);
        }
    }
}
